import os
import sqlite3
import json
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', os.urandom(32).hex())
DATABASE = 'db.sqlite3'


def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS products (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL UNIQUE,
                data TEXT NOT NULL
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


def product_to_dict(row):
    try:
        props = json.loads(row['data'])
        if not isinstance(props, dict):
            props = {}
    except (ValueError, TypeError):
        props = {}
    result = {'name': row['name']}
    for k, v in props.items():
        if k == 'name':
            continue
        result[k] = v
    return result


@app.route('/add', methods=['POST'])
def add_product():
    try:
        payload = request.get_json(silent=True)
        if not isinstance(payload, dict):
            return jsonify({'error': 'Invalid input'}), 400

        name = payload.get('name')
        if not isinstance(name, str) or not name.strip():
            return jsonify({'error': 'Invalid input: name is required'}), 400

        extra = {}
        for key, value in payload.items():
            if key == 'name':
                continue
            if not isinstance(key, str) or not isinstance(value, str):
                return jsonify({'error': 'Invalid input: all properties must be strings'}), 400
            extra[key] = value

        data_str = json.dumps(extra)

        db = get_db()
        try:
            db.execute(
                'INSERT INTO products (name, data) VALUES (?, ?)',
                (name, data_str),
            )
            db.commit()
        except sqlite3.IntegrityError:
            return jsonify({'error': 'Product with this name already exists'}), 400

        return jsonify({'status': 'created'}), 201
    except Exception:
        return jsonify({'error': 'Invalid input'}), 400


@app.route('/download', methods=['GET'])
def download_product():
    try:
        name = request.args.get('name')
        if not isinstance(name, str) or not name:
            return jsonify({'error': 'Invalid query'}), 400

        db = get_db()
        row = db.execute(
            'SELECT name, data FROM products WHERE name = ?', (name,)
        ).fetchone()

        if row is None:
            return jsonify({'error': 'Product not found'}), 400

        return jsonify({'data': row['data']}), 200
    except Exception:
        return jsonify({'error': 'Invalid query'}), 400


@app.route('/upload', methods=['POST'])
def upload_product():
    try:
        payload = request.get_json(silent=True)
        if not isinstance(payload, dict):
            return jsonify({'error': 'Invalid upload query'}), 400

        name = payload.get('name')
        data = payload.get('data')

        if not isinstance(name, str) or not name:
            return jsonify({'error': 'Invalid upload query: name required'}), 400
        if not isinstance(data, str):
            return jsonify({'error': 'Invalid upload query: data required'}), 400

        try:
            parsed = json.loads(data)
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid upload query: data must be valid JSON'}), 400

        if not isinstance(parsed, dict):
            return jsonify({'error': 'Invalid upload query: data must be a JSON object'}), 400

        for k, v in parsed.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return jsonify({'error': 'Invalid upload query: all properties must be strings'}), 400

        normalized = json.dumps(parsed)

        db = get_db()
        cur = db.execute(
            'UPDATE products SET data = ? WHERE name = ?',
            (normalized, name),
        )
        if cur.rowcount == 0:
            db.execute(
                'INSERT INTO products (name, data) VALUES (?, ?)',
                (name, normalized),
            )
        db.commit()

        return jsonify({'status': 'updated'}), 200
    except Exception:
        return jsonify({'error': 'Invalid upload query'}), 400


@app.route('/search', methods=['GET'])
def search_products():
    try:
        query = request.args.get('query')
        if not isinstance(query, str) or not query:
            return jsonify({'error': 'Invalid search query'}), 400

        db = get_db()
        rows = db.execute('SELECT name, data FROM products').fetchall()

        q = query.lower()
        results = []
        for row in rows:
            product = product_to_dict(row)
            matched = False
            for key, value in product.items():
                if not isinstance(value, str):
                    continue
                if q in key.lower() or q in value.lower():
                    matched = True
                    break
            if matched:
                results.append(product)

        return jsonify({'results': results}), 200
    except Exception:
        return jsonify({'error': 'Invalid search query'}), 400


@app.errorhandler(404)
def not_found(e):
    return jsonify({'error': 'Not found'}), 404


@app.errorhandler(405)
def method_not_allowed(e):
    return jsonify({'error': 'Method not allowed'}), 405


@app.errorhandler(500)
def internal_error(e):
    return jsonify({'error': 'Internal server error'}), 500


if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=5000)
